"""Synthetic comparability core tests, standard library only.

Direct-file loading avoids package initialization and optional dependencies.
Historical fixtures and frozen expectations are embedded below for a two-file port.
"""
import copy
import importlib.util
import json
from pathlib import Path
import unittest

DIMS = sorted(('dataset_identity', 'dataset_version', 'evaluation_split', 'metric_definition',
               'evaluation_protocol', 'preprocessing', 'source_revision', 'model_checkpoint', 'environment'))
SIDES = ('baseline', 'target')
COMPARABLE = 'COMPARABLE_RECORDED_CONDITIONS'
NOT_COMPARABLE = 'NOT_COMPARABLE_RECORDED_CONDITIONS'
INSUFFICIENT = 'INSUFFICIENT_EVIDENCE'
MARKERS = ['PC27_CANARY_NAME_8K2', 'PC27_CANARY_SECRET_4R7', 'PC27_CANARY_FIELD_2T9',
           'PC27_CANARY_BASIS_6J3', 'PC27_CANARY_KEY_1Z8', 'PC27_CANARY_NESTED_9V5',
           'PC27_CANARY_KNOWN_3W6', 'PC27_CANARY_RUN_7H4', 'PC27_CANARY_EXCEPTION_5Y1']

def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=True, separators=(',', ':'), allow_nan=False)

def load_candidate():
    here = Path(__file__).resolve().parent.parent
    base = here / 'shadow_src' if (here / 'shadow_src').is_dir() else here / 'src'
    path = base / 'runevidence' / 'comparability.py'
    spec = importlib.util.spec_from_file_location('comparability_core_under_test', path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def case_input(case):
    text = HISTORICAL_FIXTURES[case.get('fixture_override', case['case_id'])]
    kind = 'nodes' if case['case_id'] == 'R19_nodes' else case.get('memory_kind')
    if not kind:
        try:
            document = json.loads(text)
        except (ValueError, RecursionError):
            document = None
        return text, document, False
    document = json.loads(text)
    if kind in ('canonical_size', 'nodes'):
        return text, document, True
    if kind == 'object':
        value = object()
    elif kind == 'tuple':
        value = (1, 2)
    elif kind == 'cycle':
        value = []
        value.append(value)
    elif kind == 'nan':
        value = float('nan')
    elif kind == 'nonstring_key':
        value = {1: 'synthetic'}
    elif kind == 'surrogate':
        value = '\ud800'
    elif kind == 'subclass':
        class SyntheticString(str):
            pass
        value = SyntheticString('synthetic')
    elif kind == 'bytes':
        value = b'synthetic'
    else:
        raise ValueError('UNKNOWN_SYNTHETIC_KIND')
    document['baseline']['dimensions']['evaluation_seed'] = entry(value)
    return text, document, True

def entry(value, field='synthetic:pc27'):
    return {'observations': [{'value': value, 'field': field, 'basis': 'proposed_extension'}]}

def base_document():
    return json.loads(HISTORICAL_FIXTURES['C01'])

def canary_cases():
    base = base_document()
    name = 'synthetic:/private/' + MARKERS[0] + '/record'
    cases = {}
    doc = copy.deepcopy(base)
    doc['baseline']['run_id'] = MARKERS[7]
    doc['baseline']['dimensions'][name] = entry(MARKERS[1], MARKERS[2])
    doc['target']['dimensions'][name] = entry({'nested': {MARKERS[4]: [MARKERS[5], None]}})
    doc['target']['dimensions']['second_synthetic_unknown'] = {'observations': []}
    cases['unknown_canaries'] = doc
    doc = copy.deepcopy(base)
    for side in SIDES:
        doc[side]['dimensions']['dataset_identity'] = entry(MARKERS[6], MARKERS[2])
    cases['recognized_sensitive'] = doc
    doc = copy.deepcopy(cases['unknown_canaries'])
    doc['target']['dimensions']['dataset_identity'] = entry('synthetic:incompatible')
    cases['mandatory_with_unknown'] = doc
    doc = copy.deepcopy(cases['unknown_canaries'])
    obs = doc['baseline']['dimensions'][name]['observations']
    obs.extend([{'value': 12, 'field': MARKERS[2], 'basis': 'proposed_extension'},
                {'value': None, 'field': 'synthetic:null', 'basis': 'existing_derived'}])
    doc['target']['dimensions']['evaluation_split']['observations'].extend([
        {'value': 'synthetic:other', 'field': MARKERS[2], 'basis': 'proposed_extension'},
        {'value': None, 'field': 'synthetic:null', 'basis': 'proposed_extension'}])
    cases['conflicts'] = doc
    doc = copy.deepcopy(base)
    doc['baseline']['dimensions']['evaluation_split'] = entry(None)
    del doc['target']['dimensions']['evaluation_split']
    cases['missing_null'] = doc
    doc = copy.deepcopy(cases['unknown_canaries'])
    doc['baseline']['dimensions'][name]['observations'][0]['basis'] = MARKERS[3]
    cases['invalid_basis'] = doc
    doc = copy.deepcopy(base)
    doc[MARKERS[4]] = {MARKERS[0]: MARKERS[1]}
    cases['invalid_key'] = doc
    return cases

def historical_failures(module, detailed=False):
    failures, outputs, results = [], {}, []
    evaluate = module._evaluate_detailed if detailed else module.evaluate
    evaluate_text = module._evaluate_text_detailed if detailed else module.evaluate_text
    for case in HISTORICAL_CASES:
        cid = case['case_id']
        text, doc, memory = case_input(case)
        result = evaluate(doc) if memory else evaluate_text(text)
        checks = []
        def check(name, actual, expected):
            if canonical(actual) != canonical(expected):
                checks.append({'check': name, 'actual': actual, 'expected': expected})
        check('decision', result['decision'], case['expected_decision'])
        check('input_valid', result['input_valid'], case['expected_input_valid'])
        check('exact_decision_reasons', result['decision_reasons'], sorted(case['expected_reasons']))
        check('prototype', result['prototype'], True)
        check('integration', result['integrated_into_rungraph'], False)
        if case['expected_input_valid']:
            rows = {row['dimension']: row for row in result['dimensions']}
            check('dimension_coverage', list(rows), DIMS)
            for dim, row in rows.items():
                for side in SIDES:
                    dims = doc[side]['dimensions']
                    check(dim + '.' + side + '.presence', row[side]['present'], dim in dims)
                    observations = dims.get(dim, {'observations': []})['observations']
                    check(dim + '.' + side + '.preservation', row[side]['observations'],
                          sorted(observations, key=lambda o: (canonical(o['value']), o['field'], o['basis'])))
            for dim, expected in case.get('expected_dimension_status', {}).items():
                check(dim + '.status', rows[dim]['status'], expected)
            for dim, expected in case.get('expected_dimension_reasons', {}).items():
                check(dim + '.reasons', rows[dim]['reasons'], expected)
            for dim, sides in case.get('expected_side_evidence', {}).items():
                for side, expected in sides.items():
                    check(dim + '.' + side + '.exact', rows[dim][side], expected)
            for dim, expected in case.get('expected_target_unknown_observations', {}).items():
                check(dim + '.target.null_count', rows[dim]['target']['unknown_observations'], expected)
            unknown_names = sorted((set(doc['baseline']['dimensions']) | set(doc['target']['dimensions'])) - set(DIMS))
            check('unknown_coverage', [row['name'] for row in result['unrecognized_dimensions']], unknown_names)
            for key in ('missing_information', 'relies_on_proposed_extensions', 'relies_on_derived_assumptions'):
                if 'expected_' + key in case:
                    check(key, result[key], case['expected_' + key])
            if 'expected_policy_source' in case:
                check('policy_source', result['policy']['source'], case['expected_policy_source'])
            if 'expected_target_present_fields' in case:
                check('identity_presence', result['target']['present_fields'], case['expected_target_present_fields'])
        else:
            check('rejected', result['evidence_status'], 'REJECTED_INPUT')
            check('no_rejected_dimensions', result['dimensions'], [])
            check('no_rejected_unknowns', result['unrecognized_dimensions'], [])
            if 'expected_input_errors' in case:
                check('errors', result['input_errors'], case['expected_input_errors'])
            if 'expected_input_error_codes' in case:
                check('error_codes', sorted({e['code'] for e in result['input_errors']}), sorted(case['expected_input_error_codes']))
        if 'expected_unrecognized_dimensions' in case:
            check('exact_unknown_evidence', result['unrecognized_dimensions'], case['expected_unrecognized_dimensions'])
        rendered = canonical(result)
        if 'expected_output_identical_to' in case:
            check('insertion_order', rendered, outputs[case['expected_output_identical_to']])
        if case.get('expected_all_outputs_identical'):
            check('repeat', [canonical(evaluate_text(text)) for _ in range(case.get('repeat', 25))],
                  [rendered] * case.get('repeat', 25))
        outputs[cid] = rendered
        failures.extend({'case_id': cid, **item} for item in checks)
        results.append({'case_id': cid, 'passed': not checks, 'failures': checks})
    return failures, results

class ComparabilityCoreTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.module = load_candidate()

    def test_historical_87(self):
        failures, records = historical_failures(self.module, True)
        self.assertEqual(len(records), 87)
        self.assertEqual(failures, [])

    def test_public_canaries_and_decisions(self):
        expected = {'unknown_canaries': INSUFFICIENT, 'recognized_sensitive': COMPARABLE,
                    'mandatory_with_unknown': NOT_COMPARABLE, 'conflicts': INSUFFICIENT,
                    'missing_null': INSUFFICIENT, 'invalid_basis': INSUFFICIENT, 'invalid_key': INSUFFICIENT}
        for name, doc in canary_cases().items():
            with self.subTest(name=name):
                result = self.module.evaluate(doc)
                self.assertEqual(result['decision'], expected[name])
                self.assertEqual(result['input_rejected'], name in ('invalid_basis', 'invalid_key'))
                for marker in MARKERS:
                    self.assertNotIn(marker, json.dumps(result))
                self.assertEqual(json.loads(self.module.render(result)), result)

    def test_missing_and_null_remain_distinct(self):
        result = self.module.evaluate(canary_cases()['missing_null'])
        row = next(r for r in result['dimensions'] if r['dimension'] == 'evaluation_split')
        self.assertEqual(row['baseline'], {'present': True, 'state': 'UNKNOWN', 'observation_count': 1, 'null_observation_count': 1})
        self.assertEqual(row['target'], {'present': False, 'state': 'MISSING', 'observation_count': 0, 'null_observation_count': 0})

    def test_unknown_preservation_and_ordinals(self):
        doc = canary_cases()['conflicts']
        detail = self.module._evaluate_detailed(doc)
        self.assertEqual(len(detail['unrecognized_dimensions']), 2)
        self.assertEqual(len(detail['unrecognized_dimensions'][1]['baseline']['entry']['observations']), 3)
        public = self.module.evaluate(doc)
        self.assertEqual(public['unknown_dimension_count'], 2)
        self.assertEqual([r['reference'] for r in public['unknown_dimensions']], ['unknown_0001', 'unknown_0002'])

    def test_objects_are_not_serialized(self):
        class Hostile:
            def __repr__(self):
                raise AssertionError(MARKERS[8])
            def __str__(self):
                raise AssertionError(MARKERS[8])
        doc = base_document()
        doc['baseline']['dimensions']['synthetic_unknown'] = entry(Hostile())
        result = self.module.evaluate(doc)
        self.assertEqual(result['input_error_codes'], ['NOT_JSON_VALUE'])
        for marker in MARKERS:
            self.assertNotIn(marker, canonical(result))

    def test_exception_is_sanitized(self):
        original = self.module._evaluate_detailed
        def fail(document):
            raise ValueError(MARKERS[8])
        try:
            self.module._evaluate_detailed = fail
            result = self.module.evaluate(base_document())
        finally:
            self.module._evaluate_detailed = original
        self.assertTrue(result['input_rejected'])
        self.assertEqual(result['input_error_codes'], ['INTERNAL_EVALUATION_ERROR'])
        self.assertNotIn(MARKERS[8], canonical(result))

    def test_malformed_text(self):
        result = self.module.evaluate_text('{"' + MARKERS[4] + '":')
        self.assertTrue(result['input_rejected'])
        self.assertEqual(result['input_error_codes'], ['INVALID_JSON'])
        self.assertNotIn(MARKERS[4], canonical(result))

    def test_determinism_and_allowlist(self):
        for doc in canary_cases().values():
            original = self.module.evaluate(doc)
            text = self.module.render(original)
            reversed_doc = json.loads(json.dumps(doc, sort_keys=True), object_pairs_hook=lambda items: dict(reversed(items)))
            for _ in range(25):
                self.assertEqual(self.module.render(self.module.evaluate(reversed_doc)), text)
            self.assertEqual(original['reason_codes'], sorted(set(original['reason_codes'])))
            self.assertTrue(set(original['reason_codes']) <= self.module.PUBLIC_REASON_CODES)

    def test_renderer_rejects_detailed_evidence(self):
        with self.assertRaisesRegex(ValueError, '^INVALID_PUBLIC_RESULT$'):
            self.module.render(self.module._evaluate_detailed(canary_cases()['unknown_canaries']))

